def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    lines = [line for line in text.split('\r\n') if line] or \
            [line for line in text.split('\n') if line]
    # The special case of a blank line between records (not at start/end): 
    # the spec wants it as one empty field [""]. We scan original lines instead.
    raw_lines = text.replace('\r\n', '\n').split('\n')

    result = []
    for i, row_str in enumerate(lines):
        row = []
        pos = 0
        while pos < len(row_str):
            if row_str[pos] == '"':
                pos += 1  # skip opening quote
                cell = ""
                while pos < len(row_str) and row_str[pos] != '"':
                    if row_str[pos:pos+2] == '""':
                        cell += '"'
                        pos += 2
                    else:
                        cell += row_str[pos]
                        pos += 1
                pos += 1  # skip closing quote
                if pos >= len(row_str) or row_str[pos] != delimiter:
                    raise ValueError("invalid CSV")
                row.append(cell)
            else:
                next_delim = row_str.find(delimiter, pos)
                field = row_str[pos:next_delim] if next_delim == -1 else row_str[pos:next_delim]
                row.append(field)
                pos += len(field)
            if pos < len(row_str) and row_str[pos] == delimiter:
                pos += 1
        result.append(row)

    # Fix middle empty lines to [""] per requirement
    for i in range(len(raw_lines)):
        if not raw_lines[i] and 0 < i < len(raw_lines)-1:
            result[i] = [""]

    return result
```

